"""Register in captures.txt every single-command capture file that is not listed yet.

Usage:  python tools/docs/sync_captures.py [--dry-run]

A capture file under docs/_captures/<key>/<name>.txt whose first line is '$ gridsim <args>' and which holds no other
'$ ' command line is a single-command capture; capture.ps1 can regenerate it, so it belongs in captures.txt as
'<key> | <name> | <args>'. Multi-command files and file dumps are reported, not registered: they are regenerated by hand.
Fails loud on a capture whose first line is not a command.
"""
import os
import sys

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
LIST = os.path.join(ROOT, "tools", "docs", "captures.txt")


def main(argv):
    dry = "--dry-run" in argv
    with open(LIST, encoding="ascii") as f:
        text = f.read()
    known = set()
    for line in text.split("\n"):
        parts = [p.strip() for p in line.split("|")]
        if len(parts) == 3 and not line.lstrip().startswith("#"):
            known.add((parts[0], parts[1]))
    base = os.path.join(ROOT, "docs", "_captures")
    added, manual = [], []
    for key in sorted(os.listdir(base)):
        d = os.path.join(base, key)
        if not os.path.isdir(d):
            continue
        for fn in sorted(os.listdir(d)):
            if not fn.endswith(".txt"):
                continue
            name = fn[:-4]
            if (key, name) in known:
                continue
            with open(os.path.join(d, fn), encoding="utf-8", errors="replace") as f:
                lines = f.read().split("\n")
            cmds = [l for l in lines if l.startswith("$ ")]
            if len(cmds) == 1 and lines[0].startswith("$ gridsim "):
                added.append("%s | %s | %s" % (key, name, lines[0][len("$ gridsim "):].strip()))
            else:
                manual.append("%s/%s (%d commands)" % (key, fn, len(cmds)))
    for a in added:
        print("add     " + a)
    for m in manual:
        print("manual  " + m)
    if added and not dry:
        with open(LIST, "a", encoding="ascii", newline="\n") as f:
            f.write("\n# registered by sync_captures.py\n" + "\n".join(added) + "\n")
    print("%d added, %d multi-command or dump files left to regenerate by hand%s"
          % (len(added), len(manual), " (dry run)" if dry else ""))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
